def _metadata_predicate(
    metadata_filter: CheckpointMetadata,
) -> Tuple[str, Tuple[Any, ...]]:
    """Return a WHERE clause predicate for filtering checkpoints by metadata.

    This function returns a tuple of a string and a tuple of values. The string
    is the parametrized WHERE clause predicate (excluding the WHERE keyword):
    "json_extract(CAST(metadata AS TEXT), '$.key1') = ? AND ...". The tuple of
    values contains the values for each of the corresponding parameters.

    Args:
        metadata_filter (CheckpointMetadata): The metadata filter to use for filtering the checkpoints.

    Returns:
        Tuple[str, Tuple[Any, ...]]: A tuple of the predicate string and its parameter values.
    """

    def _where_value(query_value: Any) -> Tuple[str, Any]:
        """Return tuple of operator and value for a WHERE clause predicate."""
        if query_value is None:
            return ("IS ?", None)
        elif (
            isinstance(query_value, str)
            or isinstance(query_value, int)
            or isinstance(query_value, float)
        ):
            return ("= ?", query_value)
        elif isinstance(query_value, bool):
            return ("= ?", 1 if query_value else 0)
        elif isinstance(query_value, dict) or isinstance(query_value, list):
            # query value for JSON object cannot have trailing space after
            # separators (, :) as SQLite's json_extract() returns JSON strings
            # without whitespace
            return ("= ?", json.dumps(query_value, separators=(",", ":")))
        else:
            return ("= ?", str(query_value))

    predicates = []
    param_values = []

    # process metadata filter
    for query_key, query_value in metadata_filter.items():
        operator, param_value = _where_value(query_value)
        predicates.append(
            f"json_extract(CAST(metadata AS TEXT), '$.{query_key}') {operator}"
        )
        param_values.append(param_value)

    predicate = " AND ".join(predicates)
    return (predicate, tuple(param_values))


